command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="108cedb5c17a1229604dc6f7a43fbc7c2eb775ab"
$candidate="700500d92442f25002fb707031d7c2ff2cb2052f"
$branch="work/shell-provider-thumbnail-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider thumbnail docs policy fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider thumbnail docs policy"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider thumbnail docs candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "persistent checkout dirty"}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider thumbnail docs checkout failed"}
& .\test.bat policy
if($LASTEXITCODE -ne 0){throw "provider thumbnail policy gate failed"}
& git diff --check $main $candidate
if($LASTEXITCODE -ne 0){throw "provider thumbnail docs diff check failed"}
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider thumbnail docs policy"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider thumbnail docs policy"}
Write-Host "SHELL_PROVIDER_THUMBNAIL_DOCS_POLICY=PASS"
